// Landing: the brand must carry its own font-size declaration (larger than body text).
const brand = page.locator('[class*="brand" i]').first();
await expect(brand).toBeVisible();
const sizes = await page.evaluate(() => {
  const b = document.querySelector('[class*="brand" i]');
  return {
    brand: parseFloat(getComputedStyle(b).fontSize),
    body: parseFloat(getComputedStyle(document.body).fontSize),
  };
});
if (!(sizes.brand > sizes.body)) {
  throw new Error('landing brand font-size not declared: brand=' + sizes.brand + ' body=' + sizes.body);
}

// Radar: the clock must have its styling rule (tabular numerals / monospace look).
await page.goto('/ops/radar');
const clock = page.locator('[class*="clock" i]').first();
await expect(clock).toBeVisible();
const clockStyle = await page.evaluate(() => {
  const c = document.querySelector('[class*="clock" i]');
  const cs = getComputedStyle(c);
  return { nums: cs.fontVariantNumeric, family: cs.fontFamily, body: getComputedStyle(document.body).fontFamily };
});
if (!/tabular/.test(clockStyle.nums) && clockStyle.family === clockStyle.body) {
  throw new Error('radar clock rule missing: ' + JSON.stringify(clockStyle));
}
